const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('=== Product ===');
console.log(JSON.stringify(product, null, 2));

// Get variants from rt_variants table
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-2028EE'\").all();
console.log('\n=== Variants (rt_variants table) ===');
console.log(JSON.stringify(variants, null, 2));
"
